/**
 * Tiny pixel-art toolkit. Everything is rasterised with 1px fillRect calls
 * (no anti-aliasing), so sprites keep crisp edges at any integer zoom.
 * All art in WorkVerse is generated by code: there are no external assets.
 */

export type Ctx = CanvasRenderingContext2D;
export type Pt = readonly [number, number];

export function createCanvas(w: number, h: number): { canvas: HTMLCanvasElement; ctx: Ctx } {
  const canvas = document.createElement('canvas');
  canvas.width = Math.max(1, Math.ceil(w));
  canvas.height = Math.max(1, Math.ceil(h));
  const ctx = canvas.getContext('2d')!;
  ctx.imageSmoothingEnabled = false;
  return { canvas, ctx };
}

// ---------------------------------------------------------------------------
// Colour helpers

const shadeMemo = new Map<string, string>();

/** Mixes a #rrggbb colour toward black (amt < 0) or white (amt > 0). Memoised. */
export function shade(hex: string, amt: number): string {
  const key = hex + amt;
  const hit = shadeMemo.get(key);
  if (hit) return hit;
  const n = parseInt(hex.slice(1), 16);
  const target = amt < 0 ? 0 : 255;
  const k = Math.abs(amt);
  const mixc = (c: number) => Math.round(c + (target - c) * k);
  const r = mixc((n >> 16) & 255);
  const g = mixc((n >> 8) & 255);
  const b = mixc(n & 255);
  const out = `#${((1 << 24) | (r << 16) | (g << 8) | b).toString(16).slice(1)}`;
  shadeMemo.set(key, out);
  return out;
}

/** Linear mix of two #rrggbb colours (t = 0 gives a, t = 1 gives b). */
export function mix(a: string, b: string, t: number): string {
  const x = parseInt(a.slice(1), 16);
  const y = parseInt(b.slice(1), 16);
  const m = (s: number) => Math.round(((x >> s) & 255) * (1 - t) + ((y >> s) & 255) * t);
  return `#${((1 << 24) | (m(16) << 16) | (m(8) << 8) | m(0)).toString(16).slice(1)}`;
}

/** Deterministic noise in [0, 1) from integer coordinates. */
export function hash2(x: number, y: number, seed = 0): number {
  let h = Math.imul(x | 0, 374761393) ^ Math.imul(y | 0, 668265263) ^ Math.imul(seed | 0, 1442695041);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

const BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];
/** 4x4 ordered-dither threshold in (0, 1). */
export const bayer = (x: number, y: number) => (BAYER[((y & 3) << 2) | (x & 3)] + 0.5) / 16;

export type RGB = readonly [number, number, number];
export const hexToRgb = (hex: string): RGB => {
  const n = parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
};
export const shadeRgb = (c: RGB, amt: number): RGB => {
  const t = amt < 0 ? 0 : 255;
  const k = Math.abs(amt);
  return [Math.round(c[0] + (t - c[0]) * k), Math.round(c[1] + (t - c[1]) * k), Math.round(c[2] + (t - c[2]) * k)];
};
export const mixRgb = (a: RGB, b: RGB, t: number): RGB => [
  Math.round(a[0] + (b[0] - a[0]) * t),
  Math.round(a[1] + (b[1] - a[1]) * t),
  Math.round(a[2] + (b[2] - a[2]) * t),
];

// ---------------------------------------------------------------------------
// Primitives

export function rect(ctx: Ctx, x: number, y: number, w: number, h: number, color: string) {
  ctx.fillStyle = color;
  ctx.fillRect(x, y, w, h);
}

/** Bresenham line made of 1px squares. */
export function line(ctx: Ctx, x0: number, y0: number, x1: number, y1: number, color: string) {
  ctx.fillStyle = color;
  let dx = Math.abs(x1 - x0);
  const sx = x0 < x1 ? 1 : -1;
  let dy = -Math.abs(y1 - y0);
  const sy = y0 < y1 ? 1 : -1;
  let err = dx + dy;
  for (;;) {
    ctx.fillRect(x0, y0, 1, 1);
    if (x0 === x1 && y0 === y1) break;
    const e2 = 2 * err;
    if (e2 >= dy) {
      err += dy;
      x0 += sx;
    }
    if (e2 <= dx) {
      err += dx;
      y0 += sy;
    }
  }
}

/** Per-column vertical extent of a convex polygon, snapped to the pixel grid. */
function columns(pts: Pt[], each: (x: number, top: number, bottom: number) => void) {
  let minX = Infinity;
  let maxX = -Infinity;
  for (const [x] of pts) {
    minX = Math.min(minX, x);
    maxX = Math.max(maxX, x);
  }
  for (let x = Math.floor(minX); x < Math.ceil(maxX); x++) {
    const xc = x + 0.5;
    let lo = Infinity;
    let hi = -Infinity;
    for (let i = 0; i < pts.length; i++) {
      const [x1, y1] = pts[i];
      const [x2, y2] = pts[(i + 1) % pts.length];
      if (x1 === x2) continue;
      const a = Math.min(x1, x2);
      const b = Math.max(x1, x2);
      if (xc < a || xc >= b) continue;
      const y = y1 + ((xc - x1) * (y2 - y1)) / (x2 - x1);
      lo = Math.min(lo, y);
      hi = Math.max(hi, y);
    }
    if (hi > lo) {
      const top = Math.round(lo);
      each(x, top, Math.max(top + 1, Math.round(hi)));
    }
  }
}

/** Fills a convex polygon with a per-column scanline, snapped to the pixel grid. */
export function fillPoly(ctx: Ctx, pts: Pt[], color: string) {
  ctx.fillStyle = color;
  columns(pts, (x, top, bottom) => ctx.fillRect(x, top, 1, bottom - top));
}

/** Fills a convex polygon with a banded top-to-bottom gradient, dithered between bands. */
export function fillPolyGrad(ctx: Ctx, pts: Pt[], c0: string, c1: string) {
  const tones = [c0, mix(c0, c1, 0.5), c1];
  columns(pts, (x, top, bot) => {
    let runStart = top;
    let runTone = -1;
    for (let y = top; y <= bot; y++) {
      let tone = -1;
      if (y < bot) {
        const v = (y + 0.5 - top) / (bot - top) + (bayer(x, y) - 0.5) * 0.14;
        tone = v < 0.55 ? 0 : v < 0.82 ? 1 : 2;
      }
      if (tone !== runTone) {
        if (runTone >= 0) {
          ctx.fillStyle = tones[runTone];
          ctx.fillRect(x, runStart, 1, y - runStart);
        }
        runStart = y;
        runTone = tone;
      }
    }
  });
}

export function outlinePoly(ctx: Ctx, pts: Pt[], color: string) {
  for (let i = 0; i < pts.length; i++) {
    const [x1, y1] = pts[i];
    const [x2, y2] = pts[(i + 1) % pts.length];
    line(ctx, Math.round(x1), Math.round(y1), Math.round(x2), Math.round(y2), color);
  }
}

/** Raw RGBA pixel buffer, used for big textured surfaces (floors, walls). */
export class Raster {
  readonly data: Uint8ClampedArray<ArrayBuffer>;
  constructor(
    readonly w: number,
    readonly h: number,
  ) {
    this.data = new Uint8ClampedArray(new ArrayBuffer(w * h * 4));
  }
  set(x: number, y: number, c: RGB) {
    if (x < 0 || y < 0 || x >= this.w || y >= this.h) return;
    const i = (y * this.w + x) * 4;
    this.data[i] = c[0];
    this.data[i + 1] = c[1];
    this.data[i + 2] = c[2];
    this.data[i + 3] = 255;
  }
  blend(x: number, y: number, c: RGB, a: number) {
    if (x < 0 || y < 0 || x >= this.w || y >= this.h) return;
    const i = (y * this.w + x) * 4;
    if (this.data[i + 3] === 0) return;
    this.data[i] += (c[0] - this.data[i]) * a;
    this.data[i + 1] += (c[1] - this.data[i + 1]) * a;
    this.data[i + 2] += (c[2] - this.data[i + 2]) * a;
  }
  filled(x: number, y: number) {
    return x >= 0 && y >= 0 && x < this.w && y < this.h && this.data[(y * this.w + x) * 4 + 3] > 0;
  }
  toCanvas(): HTMLCanvasElement {
    const { canvas, ctx } = createCanvas(this.w, this.h);
    ctx.putImageData(new ImageData(this.data, this.w, this.h), 0, 0);
    return canvas;
  }
}

/**
 * A vertical surface in iso space (a wall or a box face). `n` planes face +y
 * (lower-left on screen), `w` planes face +x (lower-right). Coordinates are
 * (a, z): `a` pixels along the plane, `z` pixels up, both from the plane origin
 * (a = 0 is the left-most column for `n`, the right-most column for `w`).
 */
export class Plane {
  constructor(
    readonly ctx: Ctx,
    readonly side: 'n' | 'w',
    readonly ox: number,
    readonly oy: number,
  ) {}
  sx(a: number) {
    return this.side === 'n' ? this.ox + a : this.ox - 1 - a;
  }
  sy(a: number, z: number) {
    return this.oy + ((a + 1) >> 1) - 1 - z;
  }
  px(a: number, z: number, color: string) {
    this.ctx.fillStyle = color;
    this.ctx.fillRect(this.sx(a), this.sy(a, z), 1, 1);
  }
  rect(a0: number, a1: number, z0: number, z1: number, color: string) {
    this.ctx.fillStyle = color;
    for (let a = a0; a < a1; a++) this.ctx.fillRect(this.sx(a), this.sy(a, z1 - 1), 1, z1 - z0);
  }
  rectFn(a0: number, a1: number, z0: number, z1: number, fn: (a: number, z: number) => string | null) {
    let last = '';
    for (let a = a0; a < a1; a++) {
      for (let z = z0; z < z1; z++) {
        const c = fn(a, z);
        if (!c) continue;
        if (c !== last) {
          this.ctx.fillStyle = c;
          last = c;
        }
        this.ctx.fillRect(this.sx(a), this.sy(a, z), 1, 1);
      }
    }
  }
  /** Straight line between two plane points. */
  line(a0: number, z0: number, a1: number, z1: number, color: string) {
    const n = Math.max(Math.abs(a1 - a0), Math.abs(z1 - z0), 1);
    for (let i = 0; i <= n; i++) this.px(Math.round(a0 + ((a1 - a0) * i) / n), Math.round(z0 + ((z1 - z0) * i) / n), color);
  }
}

export interface Box {
  /** Position inside the footprint, in tile units. */
  x: number;
  y: number;
  /** Height above the floor, in pixels. */
  z: number;
  w: number;
  d: number;
  h: number;
  top: string;
  /** Face looking toward +y (lower-left on screen). */
  left?: string;
  /** Face looking toward +x (lower-right on screen). */
  right?: string;
  /** Skip the dark outline. */
  noOutline?: boolean;
  /** Skip the ambient-occlusion gradient on the side faces. */
  flat?: boolean;
  /** Extra painting on the box surface, run right after this box is drawn. */
  detail?: (ctx: Ctx, ox: number, oy: number) => void;
}

/** Projects tile-space (x, y) and height z (px) to canvas pixels around the anchor (ox, oy). */
export const project = (ox: number, oy: number, x: number, y: number, z = 0): Pt => [
  ox + Math.round((x - y) * 32),
  oy + Math.round((x + y) * 16 - z),
];

/** Plane on the +y face (`n`) or +x face (`w`) of a box. */
export function boxPlane(ctx: Ctx, ox: number, oy: number, b: { x: number; y: number; z: number; w: number; d: number }, side: 'n' | 'w'): Plane {
  if (side === 'n') {
    const [px, py] = project(ox, oy, b.x, b.y + b.d, b.z);
    return new Plane(ctx, 'n', px, py);
  }
  const [px, py] = project(ox, oy, b.x + b.w, b.y, b.z);
  return new Plane(ctx, 'w', px, py);
}

export function drawBox(ctx: Ctx, ox: number, oy: number, b: Box) {
  const P = (x: number, y: number, z: number) => project(ox, oy, x, y, z);
  const z1 = b.z + b.h;
  const left = b.left ?? shade(b.top, -0.16);
  const right = b.right ?? shade(b.top, -0.32);
  const topFace: Pt[] = [P(b.x, b.y, z1), P(b.x + b.w, b.y, z1), P(b.x + b.w, b.y + b.d, z1), P(b.x, b.y + b.d, z1)];
  const leftFace: Pt[] = [P(b.x, b.y + b.d, z1), P(b.x + b.w, b.y + b.d, z1), P(b.x + b.w, b.y + b.d, b.z), P(b.x, b.y + b.d, b.z)];
  const rightFace: Pt[] = [P(b.x + b.w, b.y, z1), P(b.x + b.w, b.y + b.d, z1), P(b.x + b.w, b.y + b.d, b.z), P(b.x + b.w, b.y, b.z)];
  const ao = b.flat || b.h < 6 ? 0 : b.z === 0 ? 0.17 : 0.07;
  if (ao > 0) {
    fillPolyGrad(ctx, leftFace, left, shade(left, -ao));
    fillPolyGrad(ctx, rightFace, right, shade(right, -ao));
  } else {
    fillPoly(ctx, leftFace, left);
    fillPoly(ctx, rightFace, right);
  }
  fillPoly(ctx, topFace, b.top);
  if (!b.noOutline) {
    const edge = shade(b.top, -0.5);
    outlinePoly(ctx, topFace, shade(b.top, -0.28));
    // lit bevel along the two front edges of the top face
    if (b.w + b.d >= 0.5 && b.h > 0) {
      const A = P(b.x, b.y + b.d, z1);
      const B = P(b.x + b.w, b.y + b.d, z1);
      const C = P(b.x + b.w, b.y, z1);
      line(ctx, A[0], A[1], B[0], B[1], shade(b.top, 0.24));
      line(ctx, B[0], B[1], C[0], C[1], shade(b.top, 0.1));
    }
    // vertical silhouette edges
    const bl = P(b.x, b.y + b.d, b.z);
    const tl = P(b.x, b.y + b.d, z1);
    const bb = P(b.x + b.w, b.y + b.d, b.z);
    const tb = P(b.x + b.w, b.y + b.d, z1);
    const br = P(b.x + b.w, b.y, b.z);
    const tr = P(b.x + b.w, b.y, z1);
    line(ctx, bl[0], bl[1], tl[0], tl[1], edge);
    line(ctx, bb[0], bb[1], tb[0], tb[1], shade(b.top, -0.42));
    line(ctx, br[0], br[1], tr[0], tr[1], edge);
    line(ctx, bl[0], bl[1], bb[0], bb[1], edge);
    line(ctx, bb[0], bb[1], br[0], br[1], edge);
  }
  b.detail?.(ctx, ox, oy);
}

/**
 * Draws boxes back-to-front. A box is "behind" another when it is entirely on
 * the lower side of the other along x, y or z. This is the same rule the scene
 * uses for sorting sprites.
 */
export function drawBoxes(ctx: Ctx, ox: number, oy: number, boxes: Box[]) {
  const EPS = 0.001;
  const behind = (a: Box, b: Box) => a.x + a.w <= b.x + EPS || a.y + a.d <= b.y + EPS || a.z + a.h <= b.z + EPS;
  const done = new Set<number>();
  const visiting = new Set<number>();
  const order: number[] = [];
  const visit = (i: number) => {
    if (done.has(i) || visiting.has(i)) return;
    visiting.add(i);
    for (let j = 0; j < boxes.length; j++) {
      if (j !== i && behind(boxes[j], boxes[i]) && !behind(boxes[i], boxes[j])) visit(j);
    }
    visiting.delete(i);
    done.add(i);
    order.push(i);
  };
  boxes.forEach((_, i) => visit(i));
  for (const i of order) drawBox(ctx, ox, oy, boxes[i]);
}

// ---------------------------------------------------------------------------
// Organic shapes

/** Solid blob lit from the top-left: 4 tones from light to dark, with optional outline. */
export function blob(ctx: Ctx, cx: number, cy: number, rx: number, ry: number, tones: readonly [string, string, string, string], outline?: string) {
  const inside = (x: number, y: number) => (x * x) / (rx * rx) + (y * y) / (ry * ry) <= 1;
  for (let y = -ry; y <= ry; y++) {
    for (let x = -rx; x <= rx; x++) {
      if (!inside(x, y)) continue;
      if (outline && (!inside(x - 1, y) || !inside(x + 1, y) || !inside(x, y - 1) || !inside(x, y + 1))) {
        ctx.fillStyle = outline;
      } else {
        const light = (-x / rx - y / ry) * 0.5 - ((x * x) / (rx * rx) + (y * y) / (ry * ry)) * 0.25;
        ctx.fillStyle = tones[light > 0.3 ? 0 : light > 0 ? 1 : light > -0.35 ? 2 : 3];
      }
      ctx.fillRect(cx + x, cy + y, 1, 1);
    }
  }
}

/** Soft translucent flat ellipse (contact shadows, light pools): two nested steps. */
export function softEllipse(ctx: Ctx, cx: number, cy: number, rx: number, ry: number, color: string, alpha: number) {
  const prev = ctx.globalAlpha;
  ctx.fillStyle = color;
  for (let step = 0; step < 2; step++) {
    const k = step === 0 ? 1 : 0.62;
    ctx.globalAlpha = alpha * (step === 0 ? 0.6 : 0.5);
    const hy = Math.max(1, Math.round(ry * k));
    for (let y = -hy; y <= hy; y++) {
      const half = Math.round(rx * k * Math.sqrt(Math.max(0, 1 - (y * y) / (hy * hy))));
      if (half > 0) ctx.fillRect(cx - half, cy + y, half * 2, 1);
    }
  }
  ctx.globalAlpha = prev;
}
